mapper.select:
SELECT ai.* FROM bbx_alarm_info ai JOIN bbx_alarm_device ad ON ai.id = ad.alarm_id WHERE ad.device_id IN
#{deviceId}
AND ai.alarm_status != 3

SELECT COUNT(*) AS totalNum,
       COALESCE(SUM(CASE WHEN alarm_status = 3 THEN 1 ELSE 0 END),0) AS finishNum,
       (
       SELECT alarm_name
       FROM bbx_alarm_info
       where id in
           (SELECT DISTINCT alarm_id from bbx_alarm_device


                     device_id =#{condition.deviceId}


                     and tenant_id =#{condition.tenantId}

             )
         GROUP BY alarm_name ORDER BY COUNT(*) DESC LIMIT 1) AS alarmName,
       (
       SELECT COUNT(*)
       FROM bbx_alarm_info
       where id in
        (SELECT DISTINCT alarm_id from bbx_alarm_device


                device_id =#{condition.deviceId}


                and tenant_id =#{condition.tenantId}

        )
        GROUP BY alarm_name ORDER BY COUNT(*) DESC LIMIT 1) AS alarmNameNum
FROM bbx_alarm_info
where id in
(SELECT DISTINCT alarm_id from bbx_alarm_device


        device_id =#{condition.deviceId}


        and tenant_id =#{condition.tenantId}

)

WITH week_dates AS ( SELECT TRUNC(SYSDATE, 'IW') - 1 + (LEVEL - 1) AS day_date FROM DUAL CONNECT BY LEVEL <= 7 )
SELECT w.day_date AS date, COALESCE(COUNT(a.id), 0) AS count FROM week_dates w LEFT JOIN bbx_alarm_device a ON TRUNC(a.create_time) = w.day_date
AND a.device_id IN
#{deviceId}
AND a.tenant_id =#{tenantId}
GROUP BY w.day_date ORDER BY w.day_date;
